#!/usr/bin/env python3
"""Generate 100 stratified recipes for synthetic Delivery & Logistics cases.

Usage: python3 -I synth_recipes.py <out_dir> [--seed 7]
Writes <out_dir>/_recipes.jsonl (one recipe per case, 201..300) and
<out_dir>/gold_labels_synthetic.csv (the gold routing labels in the public-set vocabulary).
Recipes are built from the public cases' parameter space (catalogue tiers, routing table, queues)
with deliberately higher weight on levels 3-7 and on situations the public set lacks.
"""
import argparse
import csv
import json
import os
import random

