# Archetypes: each is a dict of gold labels plus scenario slots. owner_raw is a template; {name} fills a person.
A = []
def arch(level, issue, segment, requester, stage, owner_org, owner_raw, func, action, channel, queue, gate, risk, money, cust_input, urgency, proof, title, situation, gold_ask, outcome, boundary, twist=None, weight=1.0):
    A.append(dict(level=level, issue_type=issue, segment=segment, requester_type=requester, shipment_stage=stage, owner_org_type=owner_org, owner_raw=owner_raw,
                  recipient_function=func, action_class=action, channel=channel, queue=queue, human_gate=gate, risk_flags=risk, money_involved=money,
                  customer_input_required=cust_input, urgency=urgency, proof_standard=proof, title=title, situation=situation, gold_ask=gold_ask,
                  outcome=outcome, boundary=boundary, twist=twist, weight=weight))

