assert sum(LEVEL_QUOTA.values()) == 100


def pick_name(rng, used):
    while True:
        n = f'{rng.choice(FIRST)} {rng.choice(LAST)}'
        if n not in used:
            used.add(n); return n


def main():
    ap = argparse.ArgumentParser(); ap.add_argument('out_dir'); ap.add_argument('--seed', type=int, default=7)
    args = ap.parse_args(); rng = random.Random(args.seed); os.makedirs(args.out_dir, exist_ok=True)
    by_level = {}
    for a in A:
        by_level.setdefault(a['level'], []).append(a)
    used_names = set(); recipes = []; n = 201
    for level, quota in LEVEL_QUOTA.items():
        pool = by_level[level]
        for i in range(quota):
            a = pool[i % len(pool)] if i < len(pool) else rng.choice(pool)
            cust = pick_name(rng, used_names); biz = rng.choice(BUSINESSES); bizname = pick_name(rng, used_names)
            counter = rng.choice(COUNTERS); depot = rng.choice(DEPOTS); item = rng.choice(ITEMS)
            day = (n - 201) % 60; date = f'2026-04-{(day % 30) + 1:02d}' if day < 30 else f'2026-05-{(day - 30) + 1:02d}'
            ship = f'DL-{n}'; order = f'TG-{n}'; ret = f'RT-{n}'
            fill = dict(cust=cust, carrier=CARRIER, merchant=MERCHANT, food=FOOD, intl=INTL, broker=BROKER, counter=counter, depot=depot, biz=biz, bizname=bizname, ship=ship, order=order, ret=ret)
            owner_raw = a['owner_raw'].format(**fill)
            req_map = {'consumer': f'{cust}, recipient' if a['segment'] != 'returns' else f'{cust}, customer', 'business_counterparty': f'{bizname}, {biz} {"shipping" if a["issue_type"] in ("freight_booking",) and a["shipment_stage"] == "pre_collection" else "receiving"} coordinator',
                       'carrier_ops': rng.choice(['Dispatch', 'Exception desk', 'Depot shift coordinator', 'Freight dispatch']) + f', {CARRIER}', 'merchant_ops': f'Order control, {MERCHANT}', 'customs_broker': f'{BROKER}, appointed customs broker'}
            if a['requester_type'] == 'business_counterparty' and 'director' in a['owner_raw']:
                requester = f'{biz} account administrator'
            else:
                requester = req_map[a['requester_type']]
            if a['owner_org_type'] == 'customer':
                owner_raw = requester if a['requester_type'] == 'consumer' else f'{cust}, recipient'
            amount = round(rng.choice([4.5, 6.0, 7.5, 9.0, 12.0, 18.0, 24.0, 30.0, 32.0, 36.0, 48.0, 60.0]), 2)
            n_events = rng.choice([4, 5, 5, 5, 6])
            twist = a['twist'] or rng.choice(['extra_noise', 'attachment_reference', None, None, None])  # asserted_only only where the archetype is built for it
            verification = 'asserted_only' if twist == 'asserted_only' else rng.choice(['authenticated_session', 'authenticated_session', 'verified_by_operator'])
            cutoff = None
            if a['urgency'] in ('immediate', 'deadline_today'):
                cutoff = f'{date}T{rng.choice(["10:00", "11:30", "16:00"])}:00Z'
            elif a['urgency'] == 'deadline_bound':
                cutoff = f'{date[:-2]}{int(date[-2:]) + 1:02d}T18:00:00Z' if int(date[-2:]) < 28 else f'{date}T18:00:00Z'
            r = dict(case_id=f'SYN-{n}', case_number=str(n), source_set='synthetic_new', complexity_level=level, complexity_name=LEVEL_NAMES[level],
                     title=a['title'], issue_type=a['issue_type'], segment=a['segment'], requester_type=a['requester_type'], requester_raw=requester,
                     shipment_stage=a['shipment_stage'], owner_org_type=a['owner_org_type'], recipient_raw=owner_raw, recipient_function=a['recipient_function'],
                     action_class=a['action_class'], gold_channel=a['channel'], queue=a['queue'], human_gate=a['human_gate'], risk_flags='|'.join(a['risk_flags']),
                     money_involved=a['money_involved'], amount_gbp=amount if a['money_involved'] else None, customer_input_required=a['customer_input_required'],
                     urgency=a['urgency'], cutoff_utc=cutoff, verification_state=verification, evidence_conflict=level == 5 or twist in ('conflicting_records', 'document_mismatch'),
                     proof_standard=a['proof_standard'], twist=twist or 'none', date=date, primary_ref=ship if a['segment'] not in ('returns',) else ret,
                     order_ref=order, return_ref=ret, item=item, customer=cust, business=biz, business_person=bizname, counter=counter, depot=depot,
                     n_events=n_events, situation=a['situation'].format(**fill), gold_ask=a['gold_ask'], outcome_shape=a['outcome'], boundary=a['boundary'],
                     escalation_channel=({'consumer': 'Customer portal', 'business_counterparty': 'Business portal', 'carrier_ops': rng.choice(['Dispatch chat', 'Email', 'Depot work queue']), 'merchant_ops': 'Warehouse work queue', 'customs_broker': 'Broker portal'}[a['requester_type']]))
            recipes.append(r); n += 1
    with open(os.path.join(args.out_dir, '_recipes.jsonl'), 'w', encoding='utf-8') as fh:
        for r in recipes:
            fh.write(json.dumps(r, ensure_ascii=False) + '\n')
    cols = ['case_id', 'segment', 'issue_type', 'requester_type', 'shipment_stage', 'owner_org_type', 'recipient_function', 'action_class', 'customer_input_required', 'urgency', 'cutoff_utc', 'risk_flags', 'money_involved', 'amount_gbp_known', 'verification_state', 'evidence_conflict', 'proof_standard', 'queue', 'human_gate', 'notes', 'complexity_level', 'complexity_name', 'gold_channel', 'recipient_raw', 'twist', 'source_set']
    with open(os.path.join(args.out_dir, 'gold_labels_synthetic.csv'), 'w', encoding='utf-8', newline='') as fh:
        w = csv.writer(fh); w.writerow(cols)
        for r in recipes:
            w.writerow([r['case_id'], r['segment'], r['issue_type'], r['requester_type'], r['shipment_stage'], r['owner_org_type'], r['recipient_function'], r['action_class'],
                        str(r['customer_input_required']).lower(), r['urgency'], r['cutoff_utc'] or '', r['risk_flags'], str(r['money_involved']).lower(), r['amount_gbp'] if r['amount_gbp'] else '',
                        r['verification_state'], str(r['evidence_conflict']).lower(), r['proof_standard'], r['queue'], r['human_gate'], f"synthetic: {r['title']}; twist={r['twist']}", r['complexity_level'], r['complexity_name'],
                        r['gold_channel'], r['recipient_raw'], r['twist'], 'synthetic_new'])
    from collections import Counter
    print(json.dumps({'recipes': len(recipes), 'levels': dict(Counter(r['complexity_level'] for r in recipes)), 'twists': dict(Counter(r['twist'] for r in recipes)),
                      'action_class': dict(Counter(r['action_class'] for r in recipes)), 'owner': dict(Counter(r['owner_org_type'] for r in recipes)),
                      'verification': dict(Counter(r['verification_state'] for r in recipes)), 'channels': dict(Counter(r['gold_channel'] for r in recipes))}, indent=1))


if __name__ == '__main__':
    main()
